/*
 * RECORD THAT THE SIGNED-IN PERSON ACCEPTED THE CURRENT NOTICE (TASK-L185 §2).
 *
 * The ONLY writer of `_User.privacyVersion` and `_User.privacyAcceptedAt`.
 * The version comes from `shared/Notice`, never from the caller: a client that
 * could say which version it accepted could accept one that does not exist.
 * Accepting twice is harmless — the version is the same and the moment moves.
 * Staff accept too: the notice also describes what a coach's account holds.
 */
if (Inputs.userId !== undefined && Inputs.version !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      const version = String(Inputs.version || '');
      if (!userId) throw new Error('no account');
      if (!version) throw new Error('no notice version');
      await Noodl.Records.save(
        userId,
        { privacyVersion: version, privacyAcceptedAt: new Date().toISOString() },
        { className: '_User' }
      );
      Outputs.version = version;
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      console.error('[dbt:acceptPrivacy] refused: ' + Outputs.error + ' user=' + String(Inputs.userId || '-'));
      Outputs.failed();
    }
  })();
}
